function project(p){let dx=p.x-camera.x,dy=p.y-camera.y,dz=p.z-camera.z,depth=dx*forward.x+dy*forward.y+dz*forward.z;if(depth<.12)return null;let focal=Math.min(W,H)*.92;return{x:W/2+(dx*right.x+dy*right.y+dz*right.z)*focal/depth,y:H*.47-(dx*up.x+dy*up.y+dz*up.z)*focal/depth,d:depth,s:focal/depth}}
