function box(arr,x,y,z,w,h,d,color,topColor=color,sideColor=color){let a=V(x-w/2,y,z-d/2),b=V(x+w/2,y,z-d/2),c=V(x+w/2,y,z+d/2),dd=V(x-w/2,y,z+d/2),A=V(a.x,y+h,a.z),B=V(b.x,y+h,b.z),C=V(c.x,y+h,c.z),D=V(dd.x,y+h,dd.z);face([a,b,B,A],sideColor,arr);face([b,c,C,B],color,arr);face([c,dd,D,C],sideColor,arr);face([dd,a,A,D],color,arr);face([A,B,C,D],topColor,arr);face([dd,c,b,a],sideColor,arr)}
function cone(arr,x,y,z,r,h,color,segments=6){let tip=V(x,y+h,z),base=[];for(let i=0;i<segments;i++){let a=2*Math.PI*i/segments;base.push(V(x+Math.cos(a)*r,y,z+Math.sin(a)*r))}for(let i=0;i<segments;i++)face([base[i],base[(i+1)%segments],tip],i%2?'#253932':color,arr);face(base,color,arr)}
function ellipse(x,y,z,rx,ry,color){let p=project(V(x,y,z));if(!p)return;ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(p.x,p.y,Math.max(1,rx*p.s),Math.max(1,ry*p.s*.52),0,0,Math.PI*2);ctx.fill()}
function backdrop(){let g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#1b2431');g.addColorStop(.42,'#626458');g.addColorStop(.69,'#b19167');g.addColorStop(1,'#22231f');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);let sun=ctx.createRadialGradient(W*.72,H*.31,2,W*.72,H*.31,H*.4);sun.addColorStop(0,'rgba(239,195,131,.32)');sun.addColorStop(1,'rgba(239,195,131,0)');ctx.fillStyle=sun;ctx.fillRect(0,0,W,H);ctx.fillStyle='#31383a';ctx.beginPath();ctx.moveTo(0,H*.57);for(let i=0;i<=12;i++){let x=i*W/12,y=H*(.49+Math.sin(i*2.7)*.055+Math.cos(i*1.3)*.035);ctx.lineTo(x,y)}ctx.lineTo(W,H*.72);ctx.lineTo(0,H*.72);ctx.fill();ctx.fillStyle='rgba(17,21,22,.58)';ctx.beginPath();ctx.moveTo(0,H*.66);for(let i=0;i<=16;i++){let x=i*W/16,y=H*(.57+Math.sin(i*3.1+2)*.045);ctx.lineTo(x,y)}ctx.lineTo(W,H*.74);ctx.lineTo(0,H*.74);ctx.fill()}
