for(let z=Math.ceil((player.z+5)/17)*17;z<far;z+=17){for(let side of [-1,1]){let x=side*rand(3.2,4.2);box(arr,x,0,z,.55,rand(1.7,2.7),.55,'#656052','#88816c','#48483f');box(arr,x,2,z,.86,.22,.82,'#a08a60','#c0a36e','#716148')}}
